### **script.js**
```javascript
const canvas = document.getElementById('game-canvas');
const ctx = canvas.getContext('2d');

// Game State
const gameState = {
    players: [
        { name: "Mario", x: 300, y: 150, speed: 0, color: "#00ff00", kartStyle: "blue" },
        { name: "Luigi", x: 250, y: 200, speed: 0, color: "#00ff00", kartStyle: "green" },
        { name: "Koopa", x: 350, y: 200, speed: 0, color: "#00ff00", kartStyle: "red" },
        { name: "Yoshi", x: 400, y: 150, speed: 0, color: "#00ff00", kartStyle: "yellow" }
    ],
    trackWidth: 300,
    trackHeight: 200,
    lapCounter: [0, 0, 0, 0],
    totalLaps: 3,
    items: { boxes: 5, shells: 5, bananas: 10 },
    finishLine: { x: 300, y: 200 }
};

// Drawing Functions
function drawTrack() {
    ctx.fillStyle = "#1f5b3e";
    ctx.fillRect(0, canvas.width, canvas.height);

    ctx.beginPath();
    ctx.arc(300, 200, 150, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = "#47a8e0";
    ctx.fillRect(0, canvas.width, canvas.height);
}

function drawPlayers() {
    gameState.players.forEach((player) => {
        ctx.beginPath();
        ctx.arc(player.x, player.y, 15, 0, Math.PI * 2);
        ctx.stroke();

        ctx.fillStyle = player.color;
        ctx.fillRect(0, canvas.width, canvas.height);
    });
}

function drawItems() {
    ctx.beginPath();
    ctx.arc(gameState.items.x, gameState.items.y, 10, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = "#47a8e0";
    ctx.fillRect(0, canvas.width, canvas.height);
}

// Game Loop
function gameLoop() {
    drawTrack();
    drawPlayers();
    drawItems();

    // Update positions based on speed
    gameState.players.forEach((player) => {
        player.x += Math.sin(player.speed * 0.1) * 5;
        player.y += Math.cos(player.speed * 0.1) * 5;

        // Check lap completion
        if (player.x < 30 && player.y > 190 && gameState.lapCounter[player.name] < gameState.totalLaps) {
            gameState.lapCounter[player.name]++;
            updateHUD();
        }
    });
}

// Control Functions
function handleAccelerate() {
    gameState.players.forEach((player) => {
        player.speed += 5;
    });
    updateSpeedDisplay();
}

function handleBrake() {
    gameState.players.forEach((player) => {
        player.speed -= 5;
        if (player.speed < 0) player.speed = 0;
    });
    updateSpeedDisplay();
}

function handleLeft() {
    gameState.players.forEach((player) => {
        player.x -= 10;
    });
}

function handleRight() {
    gameState.players.forEach((player) => {
        player.x += 10;
    });
}

// HUD Updates
function updateHUD() {
    const hudElement = document.getElementById('hud');
    hudElement.innerHTML = `Position: ${gameState.lapCounter} | Lap: ${gameState.lapCounter[0]}/${gameState.totalLaps} | Speed: ${gameState.players[0].speed}`;

    const lapCounter = document.getElementById('lap-counter');
    lapCounter.textContent = `${gameState.lapCounter[0]}`;

    const speedometer = document.getElementById('speedometer');
    speedometer.textContent = `${gameState.players[0].speed} km/h`;
}

function updateSpeedDisplay() {
    const speedDisplay = document.getElementById('speed-display');
    speedDisplay.innerHTML = `Speed: ${gameState.players[0].speed}`;
}

// Start Game
document.addEventListener('DOMContentLoaded', () => {
    gameLoop();
});
```

---

### **How to Play**
1. Save all three files in the same folder
2. Open `index.html` in your browser
3. Click buttons in the controls panel to move players around the track
4. Players will race for 3 laps, with HUD showing position and speed

