## `game.js`

```javascript
// Mario Kart Web Edition - Game Engine

const canvas = document.getElementById("race-canvas");
const ctx = canvas.getContext("2d");

// ========================
// TRACK DEFINITION (Waypoints)
// ========================
const trackPoints = [
    { x: 400, y: 100 },   // Start line
    { x: 600, y: 80 },    // Right top
    { x: 700, y: 200 },   // Right upper curve
    { x: 650, y: 400 },   // Right lower curve
    { x: 400, y: 500 },   // Bottom center
    { x: 150, y: 500 },   // Bottom left
    { x: 100, y: 300 },   // Left lower curve
    { x: 200, y: 80 },    // Left upper curve
    { x: 400, y: 60 }     // Close back to start
];

const trackSegments = [];
for (let i = 0; i < trackPoints.length; i++) {
    const a = trackPoints[i];
    const b = trackPoints[(i + 1) % trackPoints.length];
    trackSegments.push({ from: a, to: b });
}

// ========================
// RACER DEFINITIONS
// ========================
const racers = [
    { name: "Mario", color: "#ff0000", kartColor: "#ffffff", speed: 2.5, type: "human" },
    { name: "Luigi", color: "#0000ff", kartColor: "#ffffff", speed: 2.2, type: "cpu" },
    { name: "Peach", color: "#ff00ff", kartColor: "#ffffff", speed: 2.3, type: "cpu" },
    { name: "Toad", color: "#0000aa", kartColor: "#ffffff", speed: 2.1, type: "cpu" }
];

// Racer state
const racerState = racers.map((r, i) => ({
    index: i,
    x: trackPoints[0].x,
    y: trackPoints[0].y,
    speed: r.speed,
    lap: 0,
    currentSegment: 0,
    item: null, // null, "banana", "shell"
    trail: []
}));

// ========================
// GAME STATE
// ========================
let gameRunning = false;
let totalLaps = 3;
let raceStartTime = 0;
let cameraX = 400;
let cameraY = 100;

// Input state
const keys = { up: false, down: false, left: false, right: false };

// ========================
// KEY INPUT HANDLING
// ========================
document.addEventListener("keydown", (e) => {
    switch (e.key) {
        case "ArrowUp": keys.up = true; break;
        case "ArrowDown": keys.down = true; break;
        case "ArrowLeft": keys.left = true; break;
        case "ArrowRight": keys.right = true; break;
    }
});

document.addEventListener("keyup", (e) => {
    switch (e.key) {
        case "ArrowUp": keys.up = false; break;
        case "ArrowDown": keys.down = false; break;
        case "ArrowLeft": keys.left = false; break;
        case "ArrowRight": keys.right = false; break;
    }
});

// ========================
// RACE START
// ========================
document.getElementById("start-btn").addEventListener("click", () => {
    if (!gameRunning) {
        gameRunning = true;
        raceStartTime = Date.now();
        resetRace();
        gameLoop();
    }
});

document.getElementById("restart-btn").addEventListener("click", () => {
    resetRace();
    gameRunning = true;
    raceStartTime = Date.now();
    gameLoop();
});

function resetRace() {
    racers.forEach((r, i) => {
        racerState[i] = {
            index: i,
            x: trackPoints[0].x,
            y: trackPoints[0].y,
            speed: r.speed,
            lap: 0,
            currentSegment: 0,
            item: null,
            trail: []
        };
    });
}

// ========================
// MOVEMENT ENGINE
// ========================
function moveRacer(racer, dt) {
    const seg = trackSegments[racer.currentSegment];
    const dx = seg.to.x - seg.from.x;
    const dy = seg.to.y - seg.from.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    const t = dist / racer.speed;

    if (t <= dt) {
        // Reached end of segment
        racer.x = seg.to.x;
        racer.y = seg.to.y;
        racer.currentSegment = (racer.currentSegment + 1) % trackSegments.length;

        if (racer.currentSegment === 0) {
            racer.lap++;
            if (racer.lap >= totalLaps) {
                finishRacer(racer);
            }
        }
    } else {
        // Move along segment
        const moveX = dx * (dt / t);
        const moveY = dy * (dt / t);
        racer.x += moveX;
        racer.y += moveY;
    }

    // Player control overrides for Mario
    if (racer.index === 0) {
        if (keys.up && racer.y > trackPoints[0].y + 50) {
            racer.y -= 30 * dt;
        }
