This file contains the game logic, including the physics engine, rendering loop, and track generation.

```javascript
// script.js

const canvas = document.getElementById('track');
const ctx = canvas.getContext('2d');

// Game State
let gameState = {
    playerX: 400,
    playerY: 300,
    speed: 0,
    direction: 0, // 0 = Up, 1 = Right, 2 = Down, 3 = Left
    lapCount: 1,
    totalLaps: 3,
    trackWidth: 600,
    trackHeight: 400,
    obstacles: [],
    coins: []
};

// Track Generation (Procedural Kamekoo-ish layout)
function generateTrack() {
    // Create a simple rectangular loop with some "decorations"
    gameState.obstacles = [
        { x: 200, y: 100, type: 'wall' },
        { x: 600, y: 300, type: 'wall' },
        { x: 400, y: 500, type: 'wall' }
    ];

    gameState.coins = [
        { x: 300, y: 200 },
        { x: 500, y: 400 },
        { x: 100, y: 300 }
    ];
}

// Input Handling
document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            gameState.speed = Math.min(gameState.speed + 5, 20); // Max speed
            break;
        case 'ArrowDown':
            gameState.speed = Math.max(gameState.speed - 5, -10); // Reverse
            break;
        case 'ArrowLeft':
            gameState.direction = (gameState.direction + 3) % 4; // Rotate left
            break;
        case 'ArrowRight':
            gameState.direction = (gameState.direction + 1) % 4; // Rotate right
            break;
    }
});

// Game Loop
function gameLoop() {
    // Update Physics
    const dx = Math.cos(gameState.direction * Math.PI / 2) * gameState.speed;
    const dy = Math.sin(gameState.direction * Math.PI / 2) * gameState.speed;

    gameState.playerX += dx;
    gameState.playerY += dy;

    // Check Boundaries (Simple loop logic)
    if (gameState.playerX < 0) gameState.playerX = canvas.width;
    if (gameState.playerX > canvas.width) gameState.playerX = 0;
    if (gameState.playerY < 0) gameState.playerY = canvas.height;
    if (gameState.playerY > canvas.height) gameState.playerY = 0;

    // Check Obstacles (Collision)
    gameState.obstacles.forEach(obs => {
        if (Math.abs(gameState.playerX - obs.x) < 20 && Math.abs(gameState.playerY - obs.y) < 20) {
            gameState.speed = 0; // Stop on collision
            gameState.direction = 0; // Reset direction
        }
    });

    // Check Coins (Collection)
    gameState.coins.forEach(coin => {
        if (Math.abs(gameState.playerX - coin.x) < 20 && Math.abs(gameState.playerY - coin.y) < 20) {
            gameState.speed += 5; // Speed boost for collecting coins
        }
    });

    // Render Frame
    renderFrame();

    requestAnimationFrame(gameLoop);
