    ctx.strokeStyle = '#ff0000';
    ctx.lineWidth = 10;
    ctx.strokeRect(0, 0, canvas.width, canvas.height);

    // Draw Player (Mario Sprite)
    ctx.fillStyle = '#ff0000'; // Mario Red
    ctx.beginPath();
    ctx.arc(gameState.playerX, gameState.playerY, 20, 0, Math.PI * 2);
    ctx.fill();

    // Draw Hat
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(gameState.playerX, gameState.playerY - 10, 10, 0, Math.PI * 2);
    ctx.fill();

    // Draw Coins
    gameState.coins.forEach(coin => {
        ctx.fillStyle = '#ffff00'; // Gold
        ctx.beginPath();
        ctx.arc(coin.x, coin.y, 10, 0, Math.PI * 2);
        ctx.fill();
    });

    // Draw Obstacles (Walls)
    gameState.obstacles.forEach(obs => {
        ctx.fillStyle = '#000000'; // Black wall
        ctx.fillRect(obs.x - 20, obs.y - 20, 40, 40);
    });

    // Update UI
    updateUI();
