        if (gameState.lapCount > gameState.totalLaps) gameState.lapCount = 1;
    }
    document.getElementById('lap-display').textContent = `Lap: ${gameState.lapCount}/${gameState.totalLaps}`;
}

// Start Game
function startGame() {
    generateTrack();
    gameLoop();
}

// Initialize
startGame();
