### 3. `script.js`
This file contains the game logic, physics engine, and rendering loop.

```javascript
// script.js

// Game State
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let player = {
    x: 50,
    y: 350,
    width: 20,
    height: 20,
    vx: 0,
    vy: 0,
    score: 0,
    isGrounded: true
};

let coins = [];
let goombas = [];

// Constants
const GRAVITY = 0.5;
const JUMP_FORCE = -10;
const MOVE_SPEED = 3;
const CANVAS_WIDTH = canvas.width;
const CANVAS_HEIGHT = canvas.height;

// Initialize Game Objects
function initGame() {
    player.x = 50;
    player.y = 350;
    player.vx = 0;
    player.vy = 0;
    player.score = 0;

    // Spawn Coins
    for (let i = 0; i < 10; i++) {
        coins.push({
            x: Math.random() * CANVAS_WIDTH,
            y: Math.random() * CANVAS_HEIGHT / 2,
            collected: false
        });
    }

    // Spawn Goombas (Enemies)
    for (let i = 0; i < 5; i++) {
        goombas.push({
            x: Math.random() * CANVAS_WIDTH,
            y: CANVAS_HEIGHT - 10, // On ground
            width: 30,
            height: 20
        });
    }

    drawGame();
}

// Input Handling
document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') player.vx = -MOVE_SPEED;
    if (e.key === 'ArrowRight') player.vx = MOVE_SPEED;
    if (e.key === 'ArrowUp' && player.isGrounded) {
        player.vy = JUMP_FORCE;
        player.isGrounded = false;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        player.vx = 0;
    }
});

// Physics Update
function updatePhysics() {
    // Apply Gravity
    if (!player.isGrounded) {
        player.vy += GRAVITY;
        player.y += player.vy;
    }

    // Ground Collision
    if (player.y + player.height >= CANVAS_HEIGHT) {
        player.y = CANVAS_HEIGHT - player.height;
        player.vy = 0;
        player.isGrounded = true;
    }

    // Horizontal Movement
    player.x += player.vx;

    // Screen Wrapping (Left/Right)
    if (player.x < 0) player.x = CANVAS_WIDTH - player.width;
    if (player.x > CANVAS_WIDTH - player.width) player.x = 0;

    // Coin Collection
    coins.forEach(coin => {
        if (!coin.collected) {
            if (Math.abs(player.x - coin.x) < 15 && Math.abs(player.y - coin.y) < 15) {
                coin.collected = true;
                player.score += 10;
                document.getElementById('score-display').textContent = player.score;
            }
        }
    });

    // Goomba Collision (Game Over/Reset)
    goombas.forEach(gumba => {
        if (player.x < gumba.x + gumba.width && 
            player.x + player.width > gumba.x && 
            player.y < gumba.y + gumba.height && 
            player.y + player.height > gumba.y) {
            // Reset game
            initGame();
        }
    });
}

// Rendering
function drawGame() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Background (Sky)
    ctx.fillStyle = '#1a1a1a'; // Dark background
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Player (Mario)
    ctx.fillStyle = '#ff0000'; // Red
    ctx.beginPath();
    ctx.arc(player.x + player.width/2, player.y + player.height/2, player.width/2, 0, Math.PI * 2);
    ctx.fill();

    // Draw Coins
    coins.forEach(coin => {
        if (!coin.collected) {
            ctx.fillStyle = '#ffff00'; // Yellow
            ctx.beginPath();
            ctx.arc(coin.x, coin.y, 5, 0, Math.PI * 2);
            ctx.fill();
        }
    });

    // Draw Goombas
    goombas.forEach(gumba => {
        ctx.fillStyle = '#ff8000'; // Orange/Red
        ctx.fillRect(gumba.x, gumba.y, gumba.width, gumba.height);
    });

    // Draw Track Lines (Simple visual aid)
    ctx.strokeStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(0, CANVAS_HEIGHT - 10);
    ctx.lineTo(CANVAS_WIDTH, CANVAS_HEIGHT - 10);
    ctx.stroke();

    updatePhysics();
    requestAnimationFrame(drawGame);
}

// Start Game
initGame();
```

