        player.isGrounded = true;
    }

    // Horizontal Movement
    player.x += player.vx;

    // Screen Wrapping (Left/Right)
    if (player.x < 0) player.x = CANVAS_WIDTH - player.width;
    if (player.x > CANVAS_WIDTH - player.width) player.x = 0;

    // Coin Collection
    coins.forEach(coin => {
        if (!coin.collected) {
            if (Math.abs(player.x - coin.x) < 15 && Math.abs(player.y - coin.y) < 15) {
                coin.collected = true;
                player.score += 10;
                document.getElementById('score-display').textContent = player.score;
            }
        }
    });

    // Goomba Collision (Game Over/Reset)
    goombas.forEach(gumba => {
        if (player.x < gumba.x + gumba.width && 
            player.x + player.width > gumba.x && 
            player.y < gumba.y + gumba.height && 
            player.y + player.height > gumba.y) {
            // Reset game
            initGame();
        }
    });
}

// Rendering
function drawGame() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Background (Sky)
    ctx.fillStyle = '#1a1a1a'; // Dark background
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Player (Mario)
    ctx.fillStyle = '#ff0000'; // Red
    ctx.beginPath();
    ctx.arc(player.x + player.width/2, player.y + player.height/2, player.width/2, 0, Math.PI * 2);
    ctx.fill();

    // Draw Coins
    coins.forEach(coin => {
        if (!coin.collected) {
            ctx.fillStyle = '#ffff00'; // Yellow
            ctx.beginPath();
            ctx.arc(coin.x, coin.y, 5, 0, Math.PI * 2);
            ctx.fill();
        }
    });

    // Draw Goombas
    goombas.forEach(gumba => {
        ctx.fillStyle = '#ff8000'; // Orange/Red
        ctx.fillRect(gumba.x, gumba.y, gumba.width, gumba.height);
    });

    // Draw Track Lines (Simple visual aid)
    ctx.strokeStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(0, CANVAS_HEIGHT - 10);
    ctx.lineTo(CANVAS_WIDTH, CANVAS_HEIGHT - 10);
    ctx.stroke();

    updatePhysics();
    requestAnimationFrame(drawGame);
}

// Start Game
initGame();
```

