/* style.css */

body {
    font-family: 'sans-serif';
}

#game-container {
    display: flex;
    justify-content: center;
}

h1 {
    text-align: left;
    color: red;
}

canvas {
    width: 800px;
    height: 400px;
}

hud {
    background-color: white;
    padding: 20px;
}

