```

---

### 3. script.js
This contains the game logic, physics, controls, and rendering.

```javascript
// script.js

const canvas = document.getElementById('track');
const ctx = canvas.getContext('2d');

// Game State
let cars = [];
let track = [];
let lapCount = 0;
let raceActive = false;

// Constants
const CAR_WIDTH = 20;
const CAR_HEIGHT = 15;
const MAX_SPEED = 8; // pixels per frame
const TRACK_LENGTH = 800; // loop back to 0

// Create Track (A simple sine wave road)
function generateTrack() {
    track = [];
    for (let x = 0; x < TRACK_LENGTH; x++) {
        // Generate a wavy road height
        let y = 200 + Math.sin(x * 0.01) * 50;
        track.push({ x: x, y: y });
    }
}

// Initialize Players (Mario, Luigi, Toad)
function initPlayers() {
    cars = [
        { id: 'mario', color: '#ff0000', name: 'Mario', x: 50, y: 200, speed: 0, lap: 0 },
        { id: 'luigi', color: '#00ff00', name: 'Luigi', x: 100, y: 200, speed: 0, lap: 0 },
        { id: 'toad', color: '#ffff00', name: 'Toad', x: 150, y: 200, speed: 0, lap: 0 }
    ];
}

// Drawing Functions
function drawCar(car) {
    ctx.fillStyle = car.color;
    ctx.fillRect(car.x, car.y, CAR_WIDTH, CAR_HEIGHT);

    // Add a simple "hat" or detail
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(car.x + 5, car.y - 5, 10, 5);
}

function drawTrack() {
    ctx.strokeStyle = '#333333';
    ctx.lineWidth = 2;

    for (let i = 0; i < track.length; i++) {
        let point = track[i];
        // Draw a line connecting points
        if (i > 0) {
            let prev = track[i-1];
            ctx.beginPath();
            ctx.moveTo(prev.x, prev.y);
            ctx.lineTo(point.x, point.y);
            ctx.stroke();
        }
    }
}

// Physics & Movement Logic
function updateGame() {
    if (!raceActive) return;

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw static track
    drawTrack();

    // Update each car
    cars.forEach(car => {
        // Accelerate
        if (car.speed < MAX_SPEED) {
            car.speed += 0.1;
        }

        // Move forward
        car.x += car.speed;

        // Loop around track
        if (car.x >= TRACK_LENGTH) {
            car.x = 0;
            car.lap++;
            updateHUD();
        }

        // Calculate Y position based on track sine wave
        let index = Math.floor(car.x);
        if (index < track.length) {
            car.y = track[index].y;
        }

        // Draw the car
        drawCar(car);
    });

    requestAnimationFrame(updateGame);
}

// UI Updates
function updateHUD() {
    document.getElementById('lap-display').innerText = cars[0].lap;

    // Sort by lap count then x position
    let sortedCars = [...cars].sort((a, b) => {
        if (a.lap !== b.lap) return a.lap - b.lap;
        return a.x - b.x;
    });

    let posIndex = cars.indexOf(sortedCars[0]); // Find Mario's rank
    let rank = sortedCars.findIndex(c => c.id === 'mario') + 1;
    document.getElementById('pos-display').innerText = rank + 'rd';
}

// Controls
document.getElementById('start-btn').onclick = () => {
    generateTrack();
    initPlayers();
    raceActive = true;
    updateGame();
};

document.getElementById('reset-btn').onclick = () => {
    raceActive = false;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    document.getElementById('lap-display').innerText = '0';
    document.getElementById('pos-display').innerText = '1st';
};

// Initial Setup
generateTrack();
initPlayers();
```

